import React, { useState } from "react";

const FAQSection = () => {
  const [activeIndex, setActiveIndex] = useState(null);

  const faqs = [
    {
      question: "How do I save books offline?",
      answer: "Go to the book page and tap 'Download' to make it available offline.",
    },
    {
      question: "Why can’t I log in?",
      answer: "Make sure your internet connection is active, and try resetting your password if needed.",
    },
    {
      question: "How can I delete my account?",
      answer: "You can delete your account from the Settings page under 'Account Management'.",
    },
    {
      question: "Can I restore my purchased books?",
      answer: "Yes, log in with the same account and your purchases will be restored automatically.",
    },
  ];

  const toggleFAQ = (index) => {
    setActiveIndex(activeIndex === index ? null : index);
  };

  const styles = {
    section: {
      marginTop: 40,
      padding: "20px",
      backgroundColor: "#f9fafb",
      borderRadius: "10px",
    },
    question: {
      cursor: "pointer",
      fontWeight: "600",
      fontSize: "1.1rem",
      padding: "10px 0",
      borderBottom: "1px solid #ddd",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
    },
    answer: {
      padding: "10px 0 15px 10px",
      color: "#555",
      lineHeight: "1.5",
    },
  };

  return (
    <section style={styles.section}>
      <h2>💡 Frequently Asked Questions</h2>
      {faqs.map((faq, index) => (
        <div key={index}>
          <div style={styles.question} onClick={() => toggleFAQ(index)}>
            {faq.question}
            <span>{activeIndex === index ? "−" : "+"}</span>
          </div>
          {activeIndex === index && <p style={styles.answer}>{faq.answer}</p>}
        </div>
      ))}
    </section>
  );
};

export default FAQSection;
